# Initially generated by GitHub Copilot.
"""Helpers to normalize provenance comments in rendered SVG files."""


def _is_valid_xml_comment_payload(text):
    """Return True when text is valid inside an XML comment.

    XML comment payload must not contain "--" and must not end with "-".
    """
    return "--" not in text and not text.endswith("-")


def normalize_generated_by_comment_hyphen(svg_text, comment_text):
    """Normalize Graphviz-escaped hyphens in one generated-by SVG comment.

    This intentionally rewrites only the exact generated-by marker text and
    leaves all other SVG entity escaping untouched. Rewriting occurs only when
    the unescaped comment text is valid for XML comments.
    """
    if not _is_valid_xml_comment_payload(comment_text):
        return svg_text
    marker = f"<!-- {comment_text} -->"
    escaped_marker = f"<!-- {comment_text.replace('-', '&#45;')} -->"
    if escaped_marker not in svg_text:
        return svg_text
    return svg_text.replace(escaped_marker, marker)
